package ktanesolver.module.modded.regular.plungerbutton;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;class PlungerButtonSolverTest{private final PlungerButtonSolver solver=new PlungerButtonSolver();@Test void coversEveryTableRowAndIndicatorBranch(){int[]pl={5,1,3,8,0,4,2,7,6,9},po={2,6,9,4,3,1,5,8,0,7},ru={8,4,6,7,1,2,0,3,9,5},ro={3,2,1,0,9,8,7,6,5,4};for(int n=0;n<10;n++){assertDigits(n,Map.of("A",true,"B",true,"C",false),pl[n],ro[n]);assertDigits(n,Map.of("A",false,"B",false,"C",true),po[n],ru[n]);assertDigits(n,Map.of("A",true,"B",false),po[n],ro[n]);}}@SuppressWarnings("unchecked")private void assertDigits(int solved,Map<String,Boolean>indicators,int press,int release){BombEntity bomb=new BombEntity();bomb.setIndicators(indicators);List<ModuleEntity>modules=new ArrayList<>();for(int i=0;i<solved;i++){ModuleEntity m=new ModuleEntity();m.setSolved(true);modules.add(m);}bomb.setModules(modules);var out=((SolveSuccess<PlungerButtonOutput>)solver.solve(new RoundEntity(),bomb,new ModuleEntity(),new PlungerButtonInput())).output();assertThat(out).isEqualTo(new PlungerButtonOutput(solved,press,release));}}
